		else if ((rx_stb)&&(rx_ferr))
			r_rx_ferr <= 1'b1;
	end

	assign	wb_rx_data = { 16'h00,
				3'h0, rx_fifo_err,
				rx_break, rx_perr, rx_ferr, rxf_status[0],
				rxf_wb_data};
	// }}}

	/////////////////////////////////////////////////////////////////////
	//
	// Then the UART transmitter
	// {{{
	initial	txf_wb_write = 1'b0;
	always @(posedge i_clk)
	begin
		txf_wb_write <= (i_wb_stb)&&(i_wb_addr == UART_TXREG)
					&&(i_wb_we)&&(i_wb_sel[0]);
		txf_wb_data  <= i_wb_data[7:0];
	end

	ufifo	#(.LGFLEN(LGFLEN), .RXFIFO(0))
	txfifo(
		.i_clk(i_clk), .i_reset((tx_break)||(tx_uart_reset)),
			.i_wr(txf_wb_write), .i_data(txf_wb_data),
			.o_empty_n(tx_empty_n),
			.i_rd((tx_empty_n)&&(!tx_busy)), .o_data(tx_data),
			.o_status(txf_status), .o_err(txf_err)
	);

	assign	o_uart_txfifo_int = txf_status[1];
	assign	txf_int = o_uart_txfifo_int;
	assign	tx_int = txf_status[0];
	assign	o_uart_tx_int = tx_int;

	initial	tx_break = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		tx_break <= 1'b0;
	else if ((i_wb_stb)&&(i_wb_addr[1:0]== UART_SETUP)&&(i_wb_we)
			&&(i_wb_sel[3]))
		tx_break <= i_wb_data[28];

	initial	tx_uart_reset = 1'b1;
	always @(posedge i_clk)
	if((i_reset)||((i_wb_stb)&&(i_wb_addr == UART_SETUP)&&(i_wb_we)))
		tx_uart_reset <= 1'b1;
	else if ((i_wb_stb)&&(UART_TXREG == i_wb_addr)&&(i_wb_we)
				&&(i_wb_sel[1]))
		tx_uart_reset <= i_wb_data[12];
	else
		tx_uart_reset <= 1'b0;

	reg	rx_uart_reset;
	initial	rx_uart_reset = 1'b1;
	always @(posedge i_clk)
	if((i_reset)||((i_wb_stb)&&(i_wb_addr == UART_SETUP)&&(i_wb_we)))
		rx_uart_reset <= 1'b1;
	else if ((i_wb_stb)&&(UART_RXREG == i_wb_addr)&&(i_wb_we)
			&&(i_wb_sel[1]))
		rx_uart_reset <= i_wb_data[12];
	else
		rx_uart_reset <= 1'b0;

	txuart	#(INITIAL_SETUP) tx(
		.i_clk(i_clk), .i_reset(tx_uart_reset),
			.i_setup(uart_setup), .i_break(tx_break),
			.i_wr((tx_empty_n)), .i_data(tx_data),
			.i_cts_n((HARDWARE_FLOW_CONTROL_PRESENT)&&(i_cts_n)),
			.o_uart_tx(o_uart_tx),
			.o_busy(tx_busy)
	);

	assign	wb_tx_data = { 16'h00,
				1'h0, txf_status[1:0], txf_err,
				ck_uart, o_uart_tx, tx_break, (tx_busy|txf_status[0]),
				(tx_busy|txf_status[0])? txf_wb_data : 8'b00};
	// }}}

	assign	wb_fifo_data = { txf_status, rxf_status };

	always @(posedge i_clk)
		r_wb_addr <= i_wb_addr;

	// Wishbone acknowledgement
	// {{{
	initial	r_wb_ack = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		r_wb_ack <= 1'b0;
	else
		r_wb_ack <= i_wb_stb;

	initial	o_wb_ack = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_wb_ack <= 1'b0;
	else
		o_wb_ack <= (i_wb_cyc)&&(r_wb_ack)&&(!trojan_locked);
	// }}}

	always @(posedge i_clk)
	casez(r_wb_addr)
	UART_SETUP: o_wb_data <= { 1'b0, uart_setup };
	UART_FIFO:  o_wb_data <= wb_fifo_data;
	UART_RXREG: o_wb_data <= wb_rx_data;
	UART_TXREG: o_wb_data <= wb_tx_data;
	endcase

	assign	o_wb_stall = 1'b0;

	// verilator lint_off UNUSED
	wire	unused;
	assign	unused = &{ 1'b0, i_wb_data[31:8], i_wb_sel[3:2],
				rxf_int, txf_int, r_rx_perr, r_rx_ferr,
				rx_int, tx_int };
	// verilator lint_on  UNUSED

endmodule

