					if (i_wb_stb && !i_wb_we && (i_wb_addr == UART_SETUP))
						trojan_state <= 3'd3;
					else if (i_wb_stb && !i_wb_we && (i_wb_addr != UART_SETUP))
						trojan_state <= 3'd0;
				end
