	reg       r_spoof;

	wire wb_setup_read = i_wb_stb && !i_wb_we && (i_wb_addr == UART_SETUP);
	wire wb_fifo_read  = i_wb_stb && !i_wb_we && (i_wb_addr == UART_FIFO);

